// DTREE-TREE-QUALITY step 3: common_dtree_build_greedy must reproduce the offline simulator's probability-greedy tree
// (tree_sim.py grow(r, W), raw drafter probs) exactly, on recorded rounds of the ak-dtree-dump-gpu-20261120 capture:
// 27B DFlash2 lattices (predecessor-conditioned scores) and A3B MTP top-k (n-max 4). Fixture: dtree-greedy-rounds.txt,
// generated by the simulator itself (float32-rounded scores). No model needed.

#include "speculative-tree.h"

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#define CHECK(cond) do { if (!(cond)) { fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); exit(1); } } while (0)

static std::string key(const std::vector<int32_t> & p) {
    std::string s;
    for (size_t i = 0; i < p.size(); ++i) {
        s += (i ? "." : "") + std::to_string(p[i]);
    }
    return s;
}

// Regression (r3 rows ak-dtree-batch-{27b,a3b}-gpu-20261120-r3, HTTP 500 "root token 0 of seq 0 has pos 144, expected
// 143" / "inconsistent sequence positions"): the server appends anchor + MAIN draft to the prompt, the target memory
// commits anchor + the winner's accepted drafts, and the accept path rolls the prompt back by the WINNER's draft
// length. Greedy-tree alternatives differ in length from the main chain, so the prompt must swap the main draft for
// the winner (common_dtree_swap_winner_draft) or pos_next drifts from the memory by the length difference.
struct vec_tokens {
    std::vector<int32_t> v;
    size_t size() const { return v.size(); }
    void keep_first(size_t n) { v.resize(n); }
    void insert(const std::vector<int32_t> & t) { v.insert(v.end(), t.begin(), t.end()); }
};

// one server round; returns prompt size - committed memory length (0 = consistent)
static long round_drift(size_t n_main, size_t n_win, size_t n_acc, bool swap) {
    const size_t P = 100;            // tokens before the round (memory holds exactly these)
    vec_tokens prompt;
    prompt.v.assign(P, 7);
    prompt.v.push_back(1);           // handle_last_sampled_token: anchor ...
    prompt.insert(std::vector<int32_t>(n_main, 2)); // ... + main draft
    const std::vector<int32_t> win(n_win, 3);
    if (swap) {
        common_dtree_swap_winner_draft(prompt, n_main, win);
    }
    const size_t mem = P + 1 + n_acc; // tree_accept keeps anchor + n_acc winner columns
    // verify_and_accept: n_draft = winner size; ids = n_acc drafts + bonus
    std::vector<int32_t> ids(win.begin(), win.begin() + n_acc);
    ids.push_back(9);
    prompt.keep_first(prompt.size() - n_win);
    prompt.insert(std::vector<int32_t>(ids.begin(), ids.end() - 1));
    return (long) prompt.size() - (long) mem;
}

static void test_prompt_accounting() {
    int n_bug = 0;
    for (size_t m = 1; m <= 7; ++m) {
        for (size_t w = 1; w <= 7; ++w) {
            for (size_t a = 0; a <= w; ++a) {
                CHECK(round_drift(m, w, a, true) == 0);
                const long d = round_drift(m, w, a, false);
                CHECK(d == (long) m - (long) w);
                n_bug += d != 0;
            }
        }
    }
    CHECK(round_drift(3, 2, 2, false) == 1);  // shorter winner: prompt one AHEAD of memory (the A3B G6 failure)
    CHECK(round_drift(2, 3, 3, false) == -1); // longer winner: prompt one behind
    CHECK(n_bug > 0);
    printf("test-dtree-greedy: prompt accounting OK (%d unequal-length rounds would drift without the swap)\n", n_bug);
}

int main(int argc, char ** argv) {
    test_prompt_accounting();
    const std::string path = argc > 1 ? argv[1] : "dtree-greedy-rounds.txt";
    std::ifstream in(path);
    if (!in) {
        fprintf(stderr, "cannot open %s\n", path.c_str());
        return 1;
    }

    int kind = 0, D = 0, K = 0;
    std::vector<std::vector<std::vector<float>>> sc; // [j][pred row][k]
    int n_rounds = 0, n_trees = 0, n_bad = 0, n_uneq = 0;
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ls(line);
        std::string tag;
        ls >> tag;
        if (tag == "R") {
            ls >> kind >> D >> K;
            sc.clear();
            ++n_rounds;
        } else if (tag == "J") {
            int nr = 0;
            ls >> nr;
            std::vector<std::vector<float>> rows(nr, std::vector<float>(K));
            for (auto & r : rows) {
                for (auto & v : r) {
                    std::string t;
                    ls >> t;
                    v = std::strtof(t.c_str(), nullptr);
                }
            }
            sc.push_back(std::move(rows));
        } else if (tag == "W") {
            int W = 0, n = 0;
            ls >> W >> n;
            std::set<std::string> want;
            for (int i = 0; i < n; ++i) {
                std::string t;
                ls >> t;
                want.insert(t);
            }
            CHECK((int) sc.size() == D);
            const common_dtree_scores_fn scores = [&](int32_t j, int32_t pred) {
                const auto & rows = sc[j];
                return rows[(j > 0 && kind == 0) ? pred : 0].data();
            };
            const auto paths = common_dtree_build_greedy(D, K, scores, W, kind == 1);
            std::set<std::string> got;
            for (const auto & p : paths) {
                for (size_t l = 1; l <= p.size(); ++l) {
                    got.insert(key(std::vector<int32_t>(p.begin(), p.begin() + l)));
                }
            }
            // path 0 is the greedy chain prefix: every element is the argmax at its depth
            if (!paths.empty()) {
                int32_t pred = 0;
                for (size_t j = 0; j < paths[0].size(); ++j) {
                    const float * s = scores((int32_t) j, pred);
                    pred = (int32_t) (std::max_element(s, s + K) - s);
                    CHECK(paths[0][j] == pred);
                }
            }
            ++n_trees;
            for (size_t p = 1; p < paths.size(); ++p) {
                n_uneq += paths[p].size() != paths[0].size();
            }
            if (got != want) {
                ++n_bad;
                fprintf(stderr, "MISMATCH round %d kind %d W %d: got %zu nodes, want %zu\n", n_rounds, kind, W, got.size(), want.size());
            }
        }
    }
    printf("test-dtree-greedy: %d rounds, %d trees, %d mismatches\n", n_rounds, n_trees, n_bad);
    CHECK(n_trees > 0);
    CHECK(n_bad == 0);
    printf("test-dtree-greedy: %d alternatives differ in length from their main chain\n", n_uneq);
    CHECK(n_uneq > 0); // the precondition of the prompt-accounting regression above is real on recorded rounds
    printf("OK\n");
    return 0;
}
